/* v5.0: re-worded flash cards. Each entry is id: [front, back]. Ids are unchanged so scores, Restudy marks and improved cards carry over.
   Fronts say exactly what to produce (Define / Formula / Calculate / Compare ...); backs are labeled model answers (Definition / Formula / Example entry / What it tells you ...).
   Drafted with Grok in per-topic batches, then checked: every original number kept, every journal entry balances, wording reviewed by hand. */
(function (r, f) { if (typeof module === "object" && module.exports) module.exports = f(); else r.FlashRewrite = f(); })(typeof self !== "undefined" ? self : this, function () {
return {
  "equation-1": ["Formula: the accounting equation then explain what it means in one sentence", "Formula: Assets = Liabilities + Equity\nWhat it tells you: Every asset was paid for by lenders (liabilities) or owners (equity)."],
  "equation-2": ["Define: asset, then list four examples", "Definition: Something the company owns or controls that will bring future economic benefit.\nExample: cash, receivables, inventory, equipment."],
  "equation-3": ["Define: liability, then list three examples", "Definition: An obligation to pay or deliver something to others in the future.\nExample: accounts payable, wages payable, loans."],
  "equation-4": ["Define: equity (owners' equity), explain what it represents and what it consists of", "Definition: The owners' residual claim: assets minus liabilities.\nWhat it tells you: Made up of contributed capital plus retained earnings."],
  "equation-5": ["Define: double-entry bookkeeping then explain how it keeps the equation in balance", "Definition: Every transaction affects at least two accounts so the equation always stays in balance; total debits = total credits."],
  "equation-6": ["State: what debits increase and what credits increase according to normal balances", "Answer: Debits increase assets and expenses; credits increase liabilities, equity and revenue."],
  "equation-7": ["Calculate: Assets $500k, liabilities $320k. What is equity? Show the working.", "Answer: $180k\nWorking: Equity = assets - liabilities = 500 - 320."],
  "equation-8": ["Apply: A company borrows $50k cash from a bank. State the effect on the accounting equation and give the journal entry.", "Answer: Assets (cash) +$50k and liabilities (notes payable) +$50k. Equity unchanged.\nExample entry: Dr Cash 50,000 / Cr Notes payable 50,000"],
  "equation-9": ["Apply: Owners invest $100k cash in the business. State the effect on the accounting equation and give the journal entry.", "Answer: Assets (cash) +$100k, equity (contributed capital) +$100k.\nExample entry: Dr Cash 100,000 / Cr Contributed capital 100,000"],
  "equation-10": ["Apply: The company pays $8k of accounts payable. State the effect on the accounting equation and give the journal entry.", "Answer: Cash -$8k and accounts payable -$8k. Both sides shrink equally; equity unchanged.\nExample entry: Dr Accounts payable 8,000 / Cr Cash 8,000"],
  "equation-11": ["Compare: GAAP vs IFRS, say who sets each and which public US firms use which", "Answer: GAAP: US generally accepted accounting principles (set by FASB). IFRS: international standards (IASB). Public US firms report under GAAP."],
  "equation-12": ["Explain: the historical cost principle and what it means for recording assets", "Definition: Most assets are recorded at what was paid for them, not today's market value."],
  "equation-13": ["Explain: the going-concern assumption and how it affects asset values on statements", "Definition: Statements assume the business will keep operating for the foreseeable future, so assets are not valued at fire-sale prices."],
  "equation-14": ["List: the four main financial statements", "Answer: Balance sheet, income statement, statement of cash flows, statement of stockholders' (owners') equity."],
  "equation-15": ["Explain in one sentence: how the financial statements connect focusing on net income and cash", "Answer: Net income (income statement) flows into retained earnings (balance sheet); the cash flow statement explains the change in the balance sheet's cash."],
  "balance-1": ["Define: balance sheet, say what it shows and give an example date", "Definition: A snapshot of assets, liabilities and equity on one date, e.g. December 31."],
  "balance-2": ["Compare: current vs long-term assets and liabilities including the time periods", "Answer: Current = turns into cash or comes due within one year (or the operating cycle). Long-term = beyond one year."],
  "balance-3": ["List: typical current assets in liquidity order", "Answer: Cash and equivalents, marketable securities, accounts receivable, inventory, prepaid expenses."],
  "balance-4": ["Define: accounts receivable then give example journal entries for a credit sale and cash collection", "Definition: Money customers owe for goods or services already delivered on credit.\nExample entry: Sell $5,000 on credit: Dr Accounts receivable 5,000 / Cr Sales revenue 5,000. Collect: Dr Cash 5,000 / Cr Accounts receivable 5,000."],
  "balance-5": ["Define: accounts payable then give example journal entries for a credit purchase and later payment", "Definition: Money the company owes suppliers for goods or services already received.\nExample entry: Purchase $4,000 on credit: Dr Inventory 4,000 / Cr Accounts payable 4,000. Pay: Dr Accounts payable 4,000 / Cr Cash 4,000."],
  "balance-6": ["Define: prepaid expense, say what kind of account it is, then give the journal entries for paying in advance and for using it up", "Definition: An asset: cash paid in advance for a future benefit, e.g. 12 months of insurance. Expensed as it is used up.\nExample entry: Pay $12,000 for 12 months of insurance: Dr Prepaid insurance 12,000 / Cr Cash 12,000. Each month: Dr Insurance expense 1,000 / Cr Prepaid insurance 1,000."],
  "balance-7": ["Define: unearned (deferred) revenue, say whether it is an asset or a liability, then give the journal entries for receiving cash in advance and for earning it", "Definition: A liability: cash received before the goods or service are delivered.\nExample entry: Receive $12,000 in advance: Dr Cash 12,000 / Cr Unearned revenue 12,000. When earned: Dr Unearned revenue 1,000 / Cr Revenue 1,000."],
  "balance-8": ["Define: property plant and equipment (PP&E), say how it is shown on the balance sheet, then give example journal entries for purchase and depreciation", "Definition: Long-lived tangible assets. Shown at cost less accumulated depreciation = net book value.\nExample entry: Buy for cash: Dr Equipment 10,000 / Cr Cash 10,000. Depreciate: Dr Depreciation expense 2,000 / Cr Accumulated depreciation 2,000."],
  "balance-9": ["Define: accumulated depreciation, say what it is and how it affects PP&E, then give the journal entry to record it", "Definition: A contra-asset: total depreciation charged on an asset since purchase. Reduces PP&E to its net book value.\nExample entry: Dr Depreciation expense 2,000 / Cr Accumulated depreciation 2,000."],
  "balance-10": ["Define: intangible assets and goodwill, give examples of each and how goodwill is calculated", "Definition: Non-physical assets: patents, trademarks, software. Goodwill = price paid for an acquisition above the fair value of its net identifiable assets.\nExample: Patents and trademarks are intangibles. If acquisition price exceeds fair value of net assets the excess is goodwill."],
  "balance-11": ["Define: retained earnings, give the formula for ending retained earnings, and show the journal entries for closing net income and declaring a dividend", "Definition: Cumulative net income kept in the business.\nFormula: Ending RE = beginning RE + net income - dividends.\nExample entry: Close net income of $90,000 to retained earnings: Dr Income summary 90,000 / Cr Retained earnings 90,000. Declare $30,000 of dividends: Dr Retained earnings 30,000 / Cr Dividends payable 30,000."],
  "balance-12": ["Define: current portion of long-term debt, say where it is shown, and give the reclassification entry", "Definition: Principal due within the next 12 months; shown as a current liability.\nExample entry: Reclassify $20,000 of a loan due within a year: Dr Long-term debt 20,000 / Cr Current portion of long-term debt 20,000."],
  "balance-13": ["Compare: book value of equity vs market value, including how each is calculated", "Answer: Book = assets - liabilities on the balance sheet. Market = share price x shares outstanding. They usually differ."],
  "balance-14": ["Calculate: ending retained earnings. Beginning retained earnings $400k, net income $90k, dividends $30k. What is ending RE? Show the working.", "Answer: $460k.\nWorking: 400 + 90 - 30."],
  "balance-15": ["Calculate: net book value. Equipment cost $120k, accumulated depreciation $45k. What is net book value? Show the working.", "Answer: $75k.\nWorking: 120 - 45."],
  "balance-16": ["Define: treasury stock, say how it is shown on the balance sheet, then give the journal entry for a buyback", "Definition: Company shares bought back from investors. Shown as a reduction of equity (contra-equity).\nExample entry: Buy back shares: Dr Treasury stock 10,000 / Cr Cash 10,000."],
  "income-1": ["Define: income statement, say what it shows, the time period it covers, and its other common name", "Definition: Shows revenue, expenses and profit over a period (quarter or year). Also called the P&L.\nExample: A quarterly income statement might show $250k revenue, $150k expenses resulting in $100k profit for Q2."],
  "income-2": ["Formula: gross profit, then give a small numerical example", "Formula: Revenue - cost of goods sold (COGS).\nExample: Revenue $1,000 - COGS $600 = $400 gross profit.\nWhat it tells you: Measures profit after direct costs; higher means better control of production costs before operating expenses."],
  "income-3": ["Formula: operating income (EBIT), show the calculation from gross profit and what EBIT stands for", "Formula: Gross profit - operating expenses (SG&A, R&D, depreciation). Earnings before interest and taxes.\nExample: Gross profit $400k - opex $250k = $150k EBIT.\nWhat it tells you: High number shows strong core operations; low may indicate high overhead."],
  "income-4": ["Formula: net income, show what is subtracted from EBIT and its common name", "Formula: EBIT - interest expense - income tax expense. The 'bottom line'.\nExample: EBIT $150k - interest $30k - tax $30k = $90k net income.\nWhat it tells you: Final profit after all costs; high number supports dividends and growth."],
  "income-5": ["Define: cost of goods sold (COGS), list the three types of direct costs included", "Definition: The direct cost of the products sold in the period: materials, direct labor, factory overhead.\nExample: A bike maker's COGS includes tires and frames, assembler wages, and factory machine costs."],
  "income-6": ["Define: SG&A, expand the acronym and list the types of costs included", "Definition: Selling, general and administrative expenses: salaries, rent, marketing, office costs.\nExample: Sales staff pay, office rent, TV ads, and supplies are all part of SG&A."],
  "income-7": ["Formula: EBITDA, show how it is calculated from EBIT and what it proxies for", "Formula: EBIT + depreciation + amortization.\nExample: EBIT $150k + dep $40k + amort $10k = $200k EBITDA.\nWhat it tells you: A rough proxy for operating cash earnings."],
  "income-8": ["Formula: earnings per share (EPS), write the full formula", "Formula: (Net income - preferred dividends) / weighted average common shares outstanding.\nExample: ($2.4M - $0) / 1.2M shares = $2.00 EPS.\nWhat it tells you: Higher EPS means more profit per share for owners."],
  "income-9": ["Calculate: operating income given Revenue $1,000k, COGS $600k, operating expenses $250k. Show the working.", "Answer: $150k\nWorking: Gross profit 400 - opex 250."],
  "income-10": ["Calculate: net income given EBIT $150k, interest $30k, tax rate 25%. Show the working.", "Answer: $90k\nWorking: Pre-tax 120; tax 30; net income 90."],
  "income-11": ["Calculate: EPS given Net income $2.4M, 1.2M shares, no preferred. Show the working.", "Answer: $2.00 per share.\nWorking: (2.4M net - 0) / 1.2M shares = $2.00"],
  "income-12": ["Explain: revenue recognition principle, then give a business example with journal entries", "Definition: Record revenue when it is earned (goods or services delivered to the customer), not when cash arrives.\nExample entry: Sell goods on credit: Dr Accounts receivable 5,000 / Cr Revenue 5,000. Later cash receipt: Dr Cash 5,000 / Cr Accounts receivable 5,000."],
  "income-13": ["Define: non-operating items, say where they are reported and list examples", "Definition: Gains, losses, interest income and expense that are not part of the core business; reported below operating income.\nExample: Interest on loans or a one-time gain from asset sale."],
  "income-14": ["Formula: effective tax rate, write the formula", "Formula: Income tax expense / pre-tax income.\nExample: Tax expense $30k on $120k pre-tax = 25% effective rate.\nWhat it tells you: Actual tax burden as percent of pre-tax income."],
  "cashflow-1": ["Define: statement of cash flows, and list its three main sections", "Definition: Explains the change in cash over a period in three sections: operating, investing, financing."],
  "cashflow-2": ["Define: operating activities on the statement of cash flows, and list typical items included (US GAAP)", "Definition: Cash from running the business: collections from customers, payments to suppliers and employees, interest and taxes (US GAAP)."],
  "cashflow-3": ["Define: investing activities on the cash flow statement, and list common examples", "Definition: Buying or selling long-term assets and investments: capex (outflow), sale of equipment, acquisitions."],
  "cashflow-4": ["Define: financing activities on the cash flow statement, and list common examples", "Definition: Cash from or to owners and lenders: issuing or repaying debt, issuing stock, buybacks, dividends paid."],
  "cashflow-5": ["Define: indirect method for cash from operations, and outline the steps", "Definition: Starts with net income, adds back non-cash expenses (depreciation), then adjusts for changes in working capital."],
  "cashflow-6": ["Explain: working-capital adjustments in the indirect method, with rules for increases and decreases in current assets and liabilities", "Explanation: Increase in a current asset (AR, inventory) subtracts cash; increase in a current liability (AP) adds cash. Decreases do the opposite."],
  "cashflow-7": ["Formula: free cash flow, then explain what it represents", "Formula: Cash from operations - capital expenditures.\nWhat it tells you: Cash left over for debt repayment, dividends or growth."],
  "cashflow-8": ["Calculate: cash from operations given net income $80k, depreciation $20k, AR up $15k, AP up $5k. Give the answer and show the working.", "Answer: $90k.\nWorking: 80 + 20 - 15 + 5."],
  "cashflow-9": ["Calculate: free cash flow given CFO $90k, capex $35k. Give the answer and show the working.", "Answer: $55k.\nWorking: 90 - 35."],
  "cashflow-10": ["Decide: which cash flow section and the net amount for paying $10k dividends and repaying $40k of loans", "Answer: Financing: -$50k."],
  "cashflow-11": ["Explain: why profit and cash differ, and list the main reasons", "Explanation: Accrual accounting timing (credit sales, inventory build-up), non-cash expenses like depreciation, and capex and debt flows that are not on the income statement."],
  "cashflow-12": ["Interpret: the red flag if profit is up but operating cash is down, and what it suggests", "What it tells you: Earnings may be low quality: receivables or inventory piling up, or aggressive revenue recognition."],
  "cashflow-13": ["State: the typical healthy pattern of signs for CFO, CFI and CFF", "Answer: CFO positive, CFI negative (investing in the business), CFF either sign."],
  "cashflow-14": ["Calculate: ending cash given beginning cash $40k, CFO +$90k, CFI -$60k, CFF -$20k. Give the answer and show the working.", "Answer: $50k.\nWorking: 40 + 90 - 60 - 20."],
  "accrual-1": ["Define: accrual accounting, state when it records revenue and expenses, then give an example where it differs from cash accounting", "Definition: Records revenue when earned and expenses when incurred, regardless of when cash moves.\nExample: Delivers services worth $800 in Dec but paid in Jan: accrual records revenue in Dec even without cash."],
  "accrual-2": ["Define: cash-basis accounting, state when it records revenue and expenses, then note its simplicity and GAAP status", "Definition: Records revenue and expenses only when cash is received or paid. Simpler, but not GAAP for most companies.\nExample: Same $800 services in Dec paid in Jan: records revenue only in Jan when cash arrives."],
  "accrual-3": ["Explain in one sentence: the matching principle, then give a business example", "Definition: Expenses are recorded in the same period as the revenue they help produce.\nExample: A sale in June that incurs salesperson commissions paid in July: expense the commissions in June with the revenue."],
  "accrual-4": ["Define: depreciation, say which assets it applies to, if it is a cash expense, and give the journal entry", "Definition: Allocating the cost of a long-lived tangible asset over its useful life. A non-cash expense.\nExample entry: Dr Depreciation expense 3,000 / Cr Accumulated depreciation 3,000"],
  "accrual-5": ["Formula: straight-line depreciation. Write the formula then give an example with cost $50k, salvage $5k, 5-year life", "Formula: (Cost - salvage value) / useful life in years.\nExample: (50k - 5k) / 5 = $9k per year."],
  "accrual-6": ["Calculate: Machine cost $50k, salvage $5k, life 5 years. What is annual straight-line depreciation? Show the working.", "Answer: $9k a year.\nWorking: (50 - 5) / 5."],
  "accrual-7": ["Define: double-declining balance, give the rate formula, how it is applied each year, and any limits", "Definition: Accelerated method: rate = 2 / useful life, applied to the beginning book value each year. Never depreciate below salvage.\nExample: Asset $40k, 5-year life, rate 2/5=40% x 40k = $16k in year 1."],
  "accrual-8": ["Calculate: Asset $40k, 5-year life, double-declining. What is year 1 depreciation? Show the working.", "Answer: $16k.\nWorking: Rate 2/5 = 40% x 40k."],
  "accrual-9": ["Define: amortization, say what assets it applies to, and give the journal entry to record it", "Definition: Spreading the cost of an intangible asset (patent, software license) over its useful life.\nExample entry: Dr Amortization expense 2,000 / Cr Accumulated amortization 2,000"],
  "accrual-10": ["Define: accrued expense, use the wages example, say its balance sheet classification, and give the adjusting journal entry", "Definition: An expense incurred but not yet paid, e.g. wages earned by staff in the last week of December. Recorded as a liability.\nExample entry: Dr Wages expense 1,200 / Cr Wages payable 1,200"],
  "accrual-11": ["Define: adjusting entries, state their purpose, list the main types, and give one example entry", "Definition: End-of-period entries so revenue and expenses land in the right period: accruals, deferrals, depreciation.\nExample entry: Accrue $1,200 of unpaid wages at month end: Dr Wages expense 1,200 / Cr Wages payable 1,200."],
  "accrual-12": ["Define: FIFO, explain which costs go to COGS first, and state effects on COGS, profit and ending inventory when prices rise", "Definition: First-in, first-out: oldest inventory costs go to COGS first. When prices rise: lower COGS, higher profit, higher ending inventory."],
  "accrual-13": ["Define: LIFO, explain which costs go to COGS first, state effects when prices rise, and its GAAP vs IFRS status", "Definition: Last-in, first-out: newest costs go to COGS first. When prices rise: higher COGS, lower taxable income. Allowed under US GAAP, banned under IFRS."],
  "accrual-14": ["Calculate: Bought 10 units at $5, then 10 at $7. Sold 12. What is COGS under FIFO? Show the working.", "Answer: $64.\nWorking: 10 x 5 + 2 x 7."],
  "accrual-15": ["Calculate: Bought 10 units at $5, then 10 at $7. Sold 12. What is COGS under LIFO? Show the working.", "Answer: $80.\nWorking: 10 x 7 + 2 x 5."],
  "accrual-16": ["Define: allowance for doubtful accounts, say its account type, the net AR formula, and give the journal entry to increase it", "Definition: A contra-asset estimating receivables that won't be collected. Net AR = gross AR - allowance.\nExample entry: Dr Bad debt expense 1,800 / Cr Allowance for doubtful accounts 1,800"],
  "accrual-17": ["Explain in one sentence: the conservatism principle, then give an example of its application", "Definition: When uncertain, choose the option that does not overstate assets or income, e.g. lower of cost or market for inventory."],
  "liquidity-1": ["Current ratio: write the formula, state the comfortable range, and what under 1 warns about", "Formula: Current assets / current liabilities\nWhat it tells you: Around 1.5-2 is comfortable; under 1 is a warning.\nExample: CA $300k, CL $200k gives 1.5"],
  "liquidity-2": ["Quick (acid-test) ratio: write the full formula and the common approximation", "Formula: (Cash + marketable securities + receivables) / current liabilities. Often approximated as (current assets - inventory) / current liabilities.\nExample: CA $300k incl inventory $120k, CL $200k gives (300-120)/200 = 0.9"],
  "liquidity-3": ["Cash ratio: write the formula, say what it represents, and say what a high vs low number tells you", "Formula: (Cash + marketable securities) / current liabilities\nWhat it tells you: The strictest liquidity test.\nHigh: plenty of cash on hand to pay short-term bills, though too much idle cash may earn little. Low: relies on collecting receivables or selling inventory to pay bills, which is normal for many firms."],
  "liquidity-4": ["Working capital: write the formula and state the units it uses", "Formula: Current assets - current liabilities\nWhat it tells you: in dollars."],
  "liquidity-5": ["Explain: why the quick ratio excludes inventory", "Answer: Inventory may be slow to sell or sell at a discount, so it is the least liquid current asset."],
  "liquidity-6": ["Calculate: Current assets $300k, current liabilities $200k. What is the current ratio and working capital? Show the working.", "Answer: 1.5x; working capital $100k.\nWorking: 300k / 200k = 1.5; 300k - 200k = 100k."],
  "liquidity-7": ["Calculate: CA $300k including inventory $120k; CL $200k. What is the quick ratio? Show the working.", "Answer: 0.9x\nWorking: (300 - 120) / 200 = 0.9"],
  "liquidity-8": ["Explain: whether a current ratio can be too high and why", "Answer: Yes. It may mean idle cash, bloated inventory or slow collections: assets not working hard."],
  "liquidity-9": ["Compare: liquidity vs solvency, including what each one measures", "Answer: Liquidity = paying bills due in the next year. Solvency = meeting all obligations long term (leverage ratios)."],
  "liquidity-10": ["Calculate: Current ratio is 1.2 (CA $120k, CL $100k). Pays $10k of AP with cash. What is new current ratio? Show working and effect.", "Answer: 1.22x\nWorking: 110 / 90\nWhat it tells you: Paying down CL with cash raises a ratio that is above 1."],
  "liquidity-11": ["Define: operating cycle, give its formula and what it represents", "Definition: time from buying inventory to collecting cash\nFormula: Days inventory outstanding + days sales outstanding"],
  "liquidity-12": ["Cash conversion cycle: write the formula, what it shows, and whether lower is better", "Formula: DIO + DSO - DPO\nWhat it tells you: Days cash is tied up in operations; lower is better."],
  "leverage-1": ["Formula: debt-to-equity ratio. Write the formula (note the variations analysts use) and say what a higher number tells you", "Formula: Total liabilities / total equity (some analysts use only interest-bearing debt).\nWhat it tells you: Higher = more financial risk."],
  "leverage-2": ["Formula: debt ratio. Write the formula and explain what it shows.", "Formula: Total liabilities / total assets.\nWhat it tells you: The share of assets financed by creditors."],
  "leverage-3": ["Formula: interest coverage (times interest earned). Write the formula and what a number under about 1.5x indicates.", "Formula: EBIT / interest expense.\nWhat it tells you: Under about 1.5x is a red flag."],
  "leverage-4": ["Formula: equity multiplier. Write the formula and its relationship to D/E.", "Formula: Total assets / total equity = 1 + D/E (with D = total liabilities)."],
  "leverage-5": ["Calculate: Liabilities $600k, equity $400k. What is D/E and debt ratio? Show the working.", "Answer: D/E 1.5x; debt ratio 0.60 (600 / 1,000).\nWorking: Total assets = 600k + 400k = 1,000k; D/E = 600k / 400k = 1.5; debt ratio = 600k / 1,000k = 0.60."],
  "leverage-6": ["Calculate: EBIT $240k, interest $60k. What is interest coverage? Show the working.", "Answer: 4.0x.\nWorking: 240k / 60k = 4.0x."],
  "leverage-7": ["Explain: financial leverage upside and downside including effects on ROE, losses and risk.", "Upside: debt magnifies ROE when returns exceed the interest cost.\nDownside: it magnifies losses when they do not, and raises bankruptcy risk."],
  "leverage-8": ["Define: debt covenants, give examples, and say what happens if one is broken.", "Definition: Loan conditions, e.g. a minimum interest coverage or maximum D/E. Breaking one can let the lender demand repayment."],
  "leverage-9": ["Calculate: Debt ratio 0.5. What is D/E? Show the working.", "Answer: 1.0x. Liabilities equal equity.\nWorking: Debt ratio 0.5 means liabilities are 50% of assets so equity is also 50% of assets; thus D/E = 0.5 / 0.5 = 1.0x."],
  "leverage-10": ["Define: operating leverage and explain its effect on profits relative to sales.", "Definition: High fixed costs relative to variable costs: profits swing more than sales do."],
  "profit-1": ["Formula: gross margin. Write the formula and say what a high vs low number tells you", "Formula: Gross profit / revenue.\nWhat it tells you: Shows percentage of revenue left after COGS. High is better showing strong pricing or cost control; low suggests competitive pressure or high costs."],
  "profit-2": ["Formula: operating margin. Write the formula and say what a high vs low number tells you", "Formula: Operating income (EBIT) / revenue.\nWhat it tells you: Shows profit from core operations after operating costs. High is good indicating efficiency; low means high operating expenses relative to sales."],
  "profit-3": ["Formula: net profit margin. Write the formula and say what a high vs low number tells you", "Formula: Net income / revenue.\nWhat it tells you: Percentage of revenue turning into bottom line profit. High is better showing overall efficiency; low indicates high total costs or poor performance."],
  "profit-4": ["Formula: return on assets (ROA). Write the formula, note whether it uses average assets, and say what a high vs low number tells you", "Formula: Net income / total assets (average assets is better when available).\nWhat it tells you: Measures how efficiently the firm uses assets to generate profit. High ROA is good; low suggests assets are not being used effectively."],
  "profit-5": ["Formula: return on equity (ROE). Write the formula and say what a high vs low number tells you", "Formula: Net income / shareholders' equity.\nWhat it tells you: Shows how effectively equity is used to generate profits. High ROE is generally good for owners but can be misleading if driven by debt."],
  "profit-6": ["Formula: DuPont identity. Write the full formula for ROE using the three components", "Formula: ROE = net margin x asset turnover x equity multiplier = (NI/Sales) x (Sales/Assets) x (Assets/Equity).\nWhat it tells you: Decomposes ROE into profitability efficiency and leverage components to show what is driving returns."],
  "profit-7": ["Calculate: Net margin 5%, asset turnover 2.0, equity multiplier 1.5. What is ROE? Show the working.", "Answer: 15%.\nWorking: 0.05 x 2.0 x 1.5."],
  "profit-8": ["Calculate: Revenue $800k, net income $40k, assets $500k, equity $200k. What are net margin, ROA, ROE? Show the workings.", "Answer: Margin 5%, ROA 8%, ROE 20%.\nWorking: 40k/800k=5%; 40k/500k=8%; 40k/200k=20%."],
  "profit-9": ["Explain: why ROE can mislead and what to check alongside it", "Answer: High ROE can come from heavy debt (a small equity base) rather than good operations. Check D/E alongside it."],
  "profit-10": ["Calculate: Revenue $2M, gross profit $700k. What is gross margin? Show the working.", "Answer: 35%.\nWorking: 700k / 2M = 0.35 or 35%."],
  "profit-11": ["Interpret: what it means if gross margin is falling while revenue rises", "Answer: Pricing pressure or rising input costs; growth may be bought with discounts."],
  "profit-12": ["Formula: return on invested capital (ROIC). Write the formula, define NOPAT, and say what to compare ROIC to", "Formula: NOPAT / (debt + equity), where NOPAT = EBIT x (1 - tax rate).\nWhat it tells you: Compare it with the cost of capital."],
  "efficiency-1": ["Asset turnover: write the formula, give a mini example with numbers, and say what a high vs low number tells you", "Formula: Revenue / total assets\nExample: Revenue $400,000, total assets $200,000 = 2.0\nWhat it tells you: Sales generated per dollar of assets. Higher means more efficient use of assets; lower means less efficient."],
  "efficiency-2": ["Inventory turnover: write the formula, give a mini example with numbers, and say what a high vs low number tells you", "Formula: COGS / average inventory\nExample: COGS $300,000, average inventory $50,000 = 6 times\nWhat it tells you: Shows how many times inventory is sold per year. Higher is better (faster sales); lower means inventory sits longer."],
  "efficiency-3": ["Formula: days inventory outstanding (DIO) in two ways, give a mini example, and say what a low vs high number tells you", "Formula: 365 / inventory turnover, or average inventory / COGS x 365\nExample: If turnover is 6 then DIO = 365 / 6 ≈ 61 days\nWhat it tells you: Average days inventory is held. Lower is better (less cash tied in stock); higher is worse."],
  "efficiency-4": ["Receivables turnover: write the formula, give a mini example with numbers, and say what a high vs low number tells you", "Formula: Revenue (credit sales) / average accounts receivable\nExample: Credit sales $500,000, avg AR $100,000 = 5 times\nWhat it tells you: How efficiently receivables are collected. Higher means faster collections; lower signals slower paying customers."],
  "efficiency-5": ["Days sales outstanding (DSO): write the formula, give a mini example, and say what it tells you", "Formula: Average AR / revenue x 365\nExample: AR $100k, revenue $730k = 50 days\nWhat it tells you: Average days to collect from customers. Lower is better (faster cash inflow); higher ties up cash."],
  "efficiency-6": ["Days payables outstanding (DPO): write the formula and say what it tells you", "Formula: Average AP / COGS x 365\nWhat it tells you: Average days taken to pay suppliers."],
  "efficiency-7": ["Calculate: inventory turnover and DIO given COGS $360k, average inventory $60k. Show formulas and working.", "Answer: 6x; about 61 days\nWorking: Turnover = 360k / 60k = 6; DIO = 365 / 6 ≈ 61 days"],
  "efficiency-8": ["Calculate: DSO given revenue $730k, AR $100k. Show the working.", "Answer: 50 days\nWorking: 100 / 730 x 365 = 50 days"],
  "efficiency-9": ["Calculate: cash conversion cycle given DIO 60, DSO 45, DPO 30. Give the formula and show the working.", "Formula: DIO + DSO - DPO\nAnswer: 75 days\nWorking: 60 + 45 - 30 = 75 days"],
  "efficiency-10": ["Interpret: what rising DSO indicates about customers, credit terms, collections and impact on cash", "What it tells you: Customers are paying more slowly: looser credit terms or collection trouble. Cash gets tied up.\nExample: DSO rising from 35 to 50 days means slower collections and more cash tied in AR."],
  "efficiency-11": ["Explain: why asset turnover differs by industry, give the examples, and how to compare companies", "Example: Grocers turn assets fast at low margins; utilities and airlines turn slowly at higher margins.\nWhat it tells you: Compare within an industry."],
  "hv-1": ["Define: horizontal analysis, say what it compares, in what forms, and its other name", "Definition: Compares the same line item across periods, in dollars and %. Trend analysis."],
  "hv-2": ["Define: vertical (common-size) analysis, specify the base used for the income statement and for the balance sheet", "Definition: Expresses each line as a % of a base within one period: revenue for the income statement, total assets for the balance sheet."],
  "hv-3": ["Formula: percent change. Write the formula, then give a worked example", "Formula: (Current - prior) / prior x 100.\nExample: Revenue grew from $500k to $600k: (600k - 500k) / 500k x 100 = +20%.\nWhat it tells you: The percentage growth or reduction from the previous period."],
  "hv-4": ["Calculate: percent change if revenue grew from $500k to $600k. Show the working.", "Answer: +20%.\nWorking: (600k - 500k) / 500k x 100 = 20%."],
  "hv-5": ["Calculate: SG&A as common-size % if revenue is $2M and SG&A is $500k. Show the working.", "Answer: 25% of revenue.\nWorking: 500k / 2M = 0.25 = 25%."],
  "hv-6": ["Explain: why we use common-size statements, then give a business example", "Answer: They remove size differences so you can compare companies of different scale, or one company across years.\nExample: A $10M revenue firm and a $200M firm can be compared on marketing as % of revenue rather than raw dollars."],
  "hv-7": ["Formula: compound annual growth rate (CAGR). Write the formula.", "Formula: (Ending / beginning)^(1/years) - 1.\nWhat it tells you: The smoothed average annual growth rate over multiple years assuming compounding."],
  "hv-8": ["Calculate: CAGR if sales went from $100 to $121 over 2 years. Show the working.", "Answer: 10%.\nWorking: (121 / 100)^(1/2) - 1 = sqrt(1.21) - 1 = 10%."],
  "hv-9": ["Define: benchmarking, say what it compares ratios to and its purpose", "Definition: Comparing a company's ratios with competitors or industry averages to judge whether they are good or bad."],
  "altman-1": ["Formula: Altman Z-score for public manufacturers. Write the full equation with all coefficients and variables A-E.", "Formula: Z = 1.2A + 1.4B + 3.3C + 0.6D + 1.0E.\nWhat it tells you: Higher overall score means lower bankruptcy risk."],
  "altman-2": ["List: the five Altman Z-score components A-E and write the exact formula for each.", "Answer: A = working capital / TA; B = retained earnings / TA; C = EBIT / TA; D = market value of equity / total liabilities; E = sales / TA."],
  "altman-3": ["State: the three Altman zones in the original model and the exact Z-score cutoff for each.", "Answer: Z > 2.99 safe; 1.81-2.99 grey zone; Z < 1.81 distress.\nWhat it tells you: Above 2.99 means safe from bankruptcy; below 1.81 signals distress zone."],
  "altman-4": ["State: which Altman ratio has the biggest weight, its coefficient, and what it measures", "Answer: EBIT / total assets (x3.3): operating productivity of the assets."],
  "altman-5": ["Calculate: Altman Z-score given A 0.10, B 0.20, C 0.10, D 1.00, E 1.50. Give Z, the zone, and show the full working.", "Answer: 2.83 (grey zone).\nWorking: 1.2 x 0.10 = 0.12; 1.4 x 0.20 = 0.28; 3.3 x 0.10 = 0.33; 0.6 x 1.00 = 0.60; 1.0 x 1.50 = 1.50; total 2.83."],
  "altman-6": ["Explain: the limits of the Altman Z-score including what it was built on and how it should be used.", "Answer: Built on 1960s US manufacturers; less reliable for banks, service and private firms (Z' and Z'' variants exist). A screen, not a verdict."],
  "altman-7": ["Explain: why retained earnings is included in the Altman Z-score and what it captures.", "Answer: It captures cumulative profitability and the firm's age: young firms with little RE score lower."],
  "tenk-1": ["Define: Form 10-K, say who files it with the SEC, where to find it for free, and what 10-Q and 8-K are", "Definition: Annual report public US companies file with the SEC; free on EDGAR.\nRelated: 10-Q = quarterly report, 8-K = major-event report."],
  "tenk-2": ["Define: 10-K Item 1 and list the key topics it covers", "Definition: Business: what the company does, its segments, customers and competition.\nExample: A retailer describes its store operations, geographic segments, key suppliers and customers, and competition from e-commerce firms."],
  "tenk-3": ["Define: 10-K Item 1A and state what it covers", "Definition: Risk factors.\nExample: Lists threats such as new regulations, supply shortages, or intense industry competition that could harm results."],
  "tenk-4": ["Define: 10-K Item 7, explain what MD&A stands for, and list what it covers", "Definition: MD&A: management's discussion and analysis of results, liquidity and outlook.\nExample: Explains a sales jump due to new stores but notes liquidity strain from expansion costs and future growth plans."],
  "tenk-5": ["Define: 10-K Item 8 and list what it includes", "Definition: Financial statements and notes, with the auditor's report.\nExample: Contains the balance sheet, income statement, cash flow statement, equity statement, notes, and the auditor's opinion."],
  "tenk-6": ["Define: Notes to the financial statements, list some topics they cover, and say why they matter", "Definition: Accounting policies, debt terms, leases, segments, contingencies. Often where the real story is.\nExample: A note details lease payment schedules over 5 years or the exact terms of a $50M bank loan."],
  "tenk-7": ["List: the four types of auditor's opinions and explain what to watch for in a going concern paragraph", "Answer: Unqualified (clean), qualified, adverse, disclaimer. Watch for a 'going concern' paragraph: serious doubt about survival.\nWhat it tells you: An unqualified (clean) opinion means the statements are fairly presented; the other opinions, or a going concern paragraph, signal potential trouble."],
  "tenk-8": ["Define: Proxy statement (DEF 14A), say when it is filed and what it covers", "Definition: Filed before the annual meeting: executive pay, board elections, shareholder proposals.\nExample: Details CEO bonus targets, lists director candidates up for vote, and includes investor proposals on climate policy."],
  "tenk-9": ["Define: Sarbanes-Oxley (SOX) and list its main requirements", "Definition: 2002 law: CEO/CFO certify the financials; internal-control requirements; tighter auditor independence.\nWhat it tells you: Increases accountability and aims to restore investor confidence after major accounting scandals."],
  "cvp-1": ["Contribution margin per unit: write the formula, give a small example, and say what it tells you", "Formula: Price - variable cost per unit.\nExample: If a product sells for $50 with variable cost of $30 per unit then contribution margin per unit is $20.\nWhat it tells you: Shows how much each unit contributes toward covering fixed costs and generating profit after variable costs. Higher CM per unit is better."],
  "cvp-2": ["Contribution margin ratio: write the formula, give a small example, and say what it tells you", "Formula: Contribution margin / price (or total CM / sales).\nExample: $20 CM per unit and $50 price gives ratio of 40%.\nWhat it tells you: Shows the percentage of each sales dollar that contributes to fixed costs and profit. Higher ratio is better as it improves ability to cover fixed costs."],
  "cvp-3": ["Break-even units: write the formula, give a small example, and say what the result means", "Formula: Fixed costs / contribution margin per unit.\nExample: Fixed costs $40k and CM per unit $20 gives break-even of 2,000 units.\nWhat it tells you: The exact number of units that must be sold to have total revenues equal total costs so profit is zero."],
  "cvp-4": ["Break-even sales dollars: write the formula, give a small example, and say what the result means", "Formula: Fixed costs / contribution margin ratio.\nExample: Fixed costs $120k and CM ratio 40% gives break-even sales of $300k.\nWhat it tells you: The exact sales revenue needed for total revenues to equal total costs so profit is zero."],
  "cvp-5": ["Units for a target profit: write the formula, give a small example, and say what the result means", "Formula: (Fixed costs + target profit) / contribution margin per unit.\nExample: Fixed costs $40k, target profit $20k, CM per unit $20 gives (60k / 20) = 3,000 units.\nWhat it tells you: The number of units that must be sold to achieve the specified target profit level."],
  "cvp-6": ["Calculate: break-even units given price $50, variable cost $30, fixed costs $40k. Show the answer and working.", "Answer: 2,000 units.\nWorking: 40,000 / 20."],
  "cvp-7": ["Calculate: units to earn $20k profit given price $50, VC $30, FC $40k. Show the answer and working.", "Answer: 3,000 units.\nWorking: (40,000 + 20,000) / 20."],
  "cvp-8": ["Margin of safety: write the formula, give a small example, and say what a high vs low number tells you", "Formula: (Actual or budgeted sales - break-even sales) / actual sales.\nExample: Actual sales $500k, break-even sales $300k gives (200k / 500k) = 40%.\nWhat it tells you: Shows how far sales can drop before a loss occurs. High number means safer position; low means close to break-even."],
  "cvp-9": ["Calculate: break-even sales given fixed costs $120k, CM ratio 40%. Show the answer and working.", "Answer: $300k.\nWorking: 120k / 0.4 = 300k."],
  "cvp-10": ["Compare: fixed costs vs variable costs, with one example of each", "Answer: Fixed: same total regardless of volume in the short run (rent). Variable: total rises with volume (materials)."],
  "cvp-11": ["Describe: the master budget, listing the order of its main components", "Answer: Sales budget -> production -> purchases and expenses -> budgeted income statement, cash budget, balance sheet."],
  "cvp-12": ["Explain: variance (budget vs actual), then say when it is favorable or unfavorable and give a small example", "Answer: Favorable if actual profit beats budget (revenue higher or cost lower); unfavorable otherwise.\nExample: Budgeted profit $10k but actual profit $12k is a favorable variance of $2k."],
  "tvm-1": ["Formula: future value, write the formula using PV, r and n", "Formula: FV = PV x (1 + r)^n.\nExample: $1,000 at 10% for 2 years: 1000 x (1.1)^2 = $1,210.\nWhat it tells you: Shows the value an investment will grow to in the future with compounding."],
  "tvm-2": ["Formula: present value, write the formula using FV, r and n", "Formula: PV = FV / (1 + r)^n.\nExample: $1,210 received in 2 years at 10%: 1210 / (1.1)^2 = $1,000.\nWhat it tells you: The current worth of money to be received in the future after discounting."],
  "tvm-3": ["Calculate: future value of $1,000 invested at 10% for 2 years. Show the answer and working.", "Answer: $1,210.\nWorking: 1000 x (1 + 0.10)^2 = 1000 x 1.21 = 1,210."],
  "tvm-4": ["Calculate: present value of $1,210 received in 2 years at 10%. Show the answer and working.", "Answer: $1,000.\nWorking: 1210 / (1 + 0.10)^2 = 1210 / 1.21 = 1,000."],
  "tvm-5": ["Define: net present value (NPV), give the formula, when to accept a project and a brief example", "Definition: PV of future cash flows - initial investment.\nWhat it tells you: Accept if NPV > 0: it earns more than the cost of capital.\nExample: PV of inflows $105k minus $100k investment gives NPV of $5k so accept."],
  "tvm-6": ["Define: internal rate of return (IRR), explain the decision rule and any warnings", "Definition: The discount rate that makes NPV = 0.\nWhat it tells you: Accept if IRR > cost of capital (watch out for unusual cash-flow patterns)."],
  "tvm-7": ["Define: payback period, explain what it measures and its limitations", "Definition: Years to recover the initial investment.\nWhat it tells you: Simple, but ignores the time value of money and cash after payback."],
  "tvm-8": ["Formula: present value of a perpetuity, write both the no-growth and with-growth versions", "Formula: Annual cash flow / r. With growth: CF next year / (r - g).\nExample: $500 a year at 5%: 500 / 0.05 = $10,000.\nWhat it tells you: Value today of constant or growing infinite cash flows."],
  "tvm-9": ["Calculate: PV of a perpetuity paying $500 a year at r = 5%. Show the working.", "Answer: $10,000.\nWorking: 500 / 0.05 = 10,000."],
  "tvm-10": ["Define: cost of capital (WACC), explain what it represents and its use as a hurdle rate", "Definition: The weighted average return required by lenders and owners; the hurdle rate for investments.\nWhat it tells you: Minimum return needed on investments; use to discount cash flows in NPV."],
  "tvm-11": ["Calculate: NPV of investing $100 today to get $115 in one year at 10% cost of capital. Show answer, working and decision.", "Answer: +$4.55. Accept.\nWorking: 115 / 1.10 - 100."],
  "tvm-12": ["Explain: the rule of 72, give the formula, an example and what it approximates", "Formula: Years to double ≈ 72 / interest rate in %.\nExample: At 8%, about 9 years.\nWhat it tells you: Approximate years needed for an investment to double at a fixed compound rate."],
  "found-1": ["Define: rational-actor paradigm (Froeb), including its assumptions about people and how to change behavior", "Definition: Assume people act rationally, optimally and self-interestedly. To change behavior, change incentives.\nExample: A manager sees low sales effort. Instead of lecturing, she introduces sales commissions so self-interest drives higher effort.\nWhat it tells you: Focus on incentives to predict and influence rational self-interested behavior in business settings."],
  "found-2": ["Describe: Froeb's problem-solving method, list the key steps including the three questions to ask", "Answer: Find the bad decision; ask who made it, did they have enough information, and the incentive to decide well? Fix information or incentives.\nExample: A team misses deadlines. The project lead made the bad call with incomplete timelines and no penalty for delays. Fix by sharing better data and adding deadline bonuses.\nWhat it tells you: Bad results usually trace to missing information or bad incentives, not bad people; fix those root causes."],
  "found-3": ["List: the three ways to fix a bad decision (Froeb)", "Answer: Change (1) decision rights, (2) the information people have, or (3) incentives (evaluation and compensation).\nExample: A purchasing agent buys low-quality parts. Shift decision rights to a specialist, give accurate supplier data, and tie pay to final product quality scores.\nWhat it tells you: Aligning these three elements improves organizational decisions and outcomes."],
  "found-4": ["Define: organizational design trio and explain why alignment matters", "Definition: Decision rights + evaluation (performance measurement) + rewards. They should be aligned.\nExample: Give a regional manager decision rights over hiring, measure performance via customer satisfaction scores, and pay bonuses based on those scores.\nWhat it tells you: When the three are aligned, individual self-interest leads to good company results; misalignment causes poor decisions."],
  "found-5": ["Compare: positive vs normative economics, with one example of each", "Answer: Positive: what is (testable). Normative: what ought to be (value judgment).\nExample: Positive: A carbon tax reduces emissions 15% (testable with data). Normative: Governments ought to impose carbon taxes to save the planet (value judgment).\nWhat it tells you: Positive statements can be verified or refuted by evidence; normative ones depend on personal values."],
  "found-6": ["Define: efficiency in economics and what it requires", "Definition: Resources go to their highest-valued use; all mutually beneficial trades happen.\nExample: An efficient used-truck market sells a vehicle to the small business that gains the most productivity from it rather than leaving it idle.\nWhat it tells you: Efficient allocations maximize total value created; policies often aim to move the economy toward this outcome."],
  "found-7": ["Explain in one sentence: why voluntary trade creates wealth, then give a business example", "Answer: Assets move to people who value them more; both sides gain (buyer value > price > seller value).\nExample: A vendor sells widgets for $12 (cost $7) to a factory that values them at $18 for production. Both gain; total wealth rises by $11.\nWhat it tells you: Trade is positive-sum, not zero-sum; encouraging voluntary exchanges increases overall economic wealth."],
  "found-8": ["Define: consumer surplus, give the formula, and a numerical example", "Definition: Value to the buyer - price paid.\nFormula: Value to the buyer - price paid\nExample: A firm values a software license at $5000 but pays $3200; consumer surplus equals $1800.\nWhat it tells you: Higher consumer surplus means buyers capture more value from the deal; it measures net buyer benefit."],
  "found-9": ["Define: producer (seller) surplus, give the formula, and a numerical example", "Definition: Price received - seller's cost (or value).\nFormula: Price received - seller's cost (or value)\nExample: A supplier's cost is $60 per unit and sells for $95; producer surplus is $35 per unit.\nWhat it tells you: It shows net seller benefit from a trade; total surplus (consumer plus producer) measures gains from trade and efficiency."],
  "found-10": ["Define: ceteris paribus and explain its use when studying relationships", "Definition: 'Other things equal': change one variable and hold the rest constant.\nExample: The law of demand states that higher prices reduce quantity demanded, ceteris paribus (holding income, tastes, and substitutes fixed).\nWhat it tells you: It lets analysts isolate cause-and-effect in complex situations by freezing all other variables."],
  "oppcost-1": ["Define: opportunity cost, then give a business example", "Definition: The value of the best alternative given up when you make a choice.\nExample: A business owner choosing to use their own building for their company instead of renting it out for $24,000 a year; the opp cost is $24,000.\nWhat it tells you: Helps in making choices by considering the true cost of alternatives."],
  "oppcost-2": ["Compare: explicit vs implicit cost, with one example of each", "Explicit: out-of-pocket payments. Implicit: forgone alternatives, like the owner's time or the return on capital.\nExample: Explicit: paying rent for office space. Implicit: forgoing a salary by working in your own business."],
  "oppcost-3": ["Formula: economic profit, then give a small example with numbers", "Formula: Revenue - explicit costs - implicit costs (including the opportunity cost of capital).\nExample: If revenue is $200,000, explicit costs $120,000, implicit costs $50,000 then economic profit is $30,000.\nWhat it tells you: Measures true profit after all costs; if negative the resources would be better used elsewhere."],
  "oppcost-4": ["Formula: economic value added (EVA), write the formula then give a small example", "Formula: NOPAT - (cost of capital x invested capital).\nExample: NOPAT $500k, cost of capital 8% on $4M invested capital: 0.08 x 4000000 = $320k; EVA = 500k - 320k = $180k.\nWhat it tells you: Profit after charging for all capital used."],
  "oppcost-5": ["Calculate: economic profit. Accounting profit $100k; owner could earn $80k elsewhere; capital could earn $30k elsewhere. Show the working.", "Answer: -$10k.\nWorking: 100 - 80 - 30. Accounting profit hides a loss."],
  "oppcost-6": ["Define: the hidden-cost fallacy (Froeb), then give an example", "Definition: Ignoring the opportunity cost of assets you already own, e.g. treating owned capital as free.\nExample: Using company-owned equipment for a new project but not counting the rental income it could earn if leased to another firm."],
  "oppcost-7": ["Explain: what zero economic profit means for a firm and clarify the common misconception", "Explanation: The firm earns exactly its opportunity cost: a normal return. Not 'no money'.\nExample: A shop earning a normal salary equivalent for the owner and normal return on capital has zero economic profit but is covering all its costs."],
  "oppcost-8": ["Decide: You give up a $60k job to run a shop that earns $50k accounting profit. Is this a good idea purely financially? Calculate economic profit.", "Answer: No. Economic profit is -$10k."],
  "oppcost-9": ["Define: comparative advantage, then state what it is the basis for", "Definition: Doing what you give up least to do (lowest opportunity cost). Basis for specialization and trade.\nExample: If person A gives up less to produce good X than person B, A has comparative advantage in X.\nWhat it tells you: Encourages specialization where one has the lowest opp cost to maximize total output."],
  "marginal-1": ["Define: marginal analysis, then state the decision rule for doing more", "Definition: Compare the extra benefit with the extra cost of one more unit. Do more while MB > MC.\nExample: If one more worker adds $900 in revenue but $650 in costs, hire because MB exceeds MC.\nWhat it tells you: Continue the activity until MB = MC to maximize net benefit."],
  "marginal-2": ["Define: extent decisions (Froeb), then state when to stop the activity", "Definition: 'How much' decisions: produce, advertise or hire until marginal benefit = marginal cost.\nExample: A firm decides how much to advertise by adding ads while the extra sales revenue exceeds the extra ad cost.\nWhat it tells you: Stop increasing the activity at the point where MB = MC."],
  "marginal-3": ["State: the profit-maximizing rule in terms of MR and MC", "Formula: Produce where marginal revenue (MR) = marginal cost (MC).\nExample: A bakery produces more cakes as long as the extra revenue from one cake exceeds its extra cost.\nWhat it tells you: This quantity maximizes profit; produce more if MR > MC and less if MR < MC."],
  "marginal-4": ["Formula: marginal cost, and give its abbreviation", "Formula: Change in total cost / change in quantity. (MC = ΔTC / ΔQ)\nExample: If total cost rises from $200 to $260 for one more unit, MC is $60.\nWhat it tells you: The additional cost of producing one more unit; compare to marginal revenue for decisions."],
  "marginal-5": ["Formula: marginal revenue, and give its abbreviation", "Formula: Change in total revenue / change in quantity. (MR = ΔTR / ΔQ)\nExample: If selling one more item increases total revenue by $45, MR is $45.\nWhat it tells you: The additional revenue from selling one more unit; set equal to MC to maximize profit."],
  "marginal-6": ["Explain: why decisions should use marginal not average costs and benefits, and what averages include", "Explanation: Decisions should use marginal, not average, cost and benefit. Averages include fixed and sunk costs.\nExample: Average cost per unit is $12 but the next unit only adds $5 in variable costs; base the decision on the $5 marginal cost.\nWhat it tells you: Focus only on incremental changes and ignore sunk costs for better decisions."],
  "marginal-7": ["Decide: The next unit adds $40 of revenue and $35 of cost. Should you produce it and why?", "Answer: Yes. It adds $5 of profit.\nWorking: Marginal revenue of $40 exceeds marginal cost of $35 so the unit increases total profit by $5."],
  "marginal-8": ["Calculate: marginal cost if TC(10) = $500, TC(11) = $560. Show the working.", "Answer: $60.\nWorking: Change in total cost is 560 - 500 = 60; change in quantity is 1; MC = 60 / 1 = 60."],
  "marginal-9": ["Define: diminishing marginal returns and describe the situation", "Definition: Adding more of one input to fixed others eventually adds less and less output.\nExample: In a fixed-size restaurant kitchen, each additional cook eventually prepares fewer extra meals due to crowding.\nWhat it tells you: This leads to rising marginal costs as output per extra input falls."],
  "marginal-10": ["Explain: the all-or-nothing bonus problem and how agents respond to marginal incentives", "Definition: Agents respond to marginal incentives: a bonus paid only above a threshold gives no incentive once the threshold is safely met or out of reach.\nExample: A manager with a bonus only if sales exceed $100k has little reason to push extra sales once at $110k or when stuck at $60k.\nWhat it tells you: Such bonuses distort behavior; better to tie rewards to every extra unit of performance."],
  "marginal-11": ["State: the short-run shutdown rule, then explain the reasoning", "Rule: Keep operating if price ≥ average variable cost (revenue covers variable costs); fixed costs are paid either way.\nExample: If price is $12 per unit, AVC is $10 and fixed costs are sunk, keep producing to cover variables and offset some fixed costs.\nWhat it tells you: Shut down only if revenue fails to cover variable costs, minimizing losses to fixed costs alone."],
  "sunk-1": ["Define: sunk cost, explain its relevance to forward-looking decisions, and give a business example", "Definition: A cost already incurred that can't be recovered. Irrelevant to forward-looking decisions.\nExample: A firm paid $100k to develop a prototype that failed and has no value. That $100k is sunk.\nWhat it tells you: Ignore sunk costs and base decisions only on future costs and benefits."],
  "sunk-2": ["Define: sunk-cost fallacy, explain what causes it, and give a business example", "Definition: Continuing a project because of what you've already spent, rather than on future costs and benefits.\nExample: A company has spent $4M on a failing marketing campaign and spends another $1M to finish it just to justify the original spend even though future returns are only $0.6M.\nWhat it tells you: This error leads to throwing good money after bad; evaluate only incremental future costs and benefits."],
  "sunk-3": ["Decide: $2M already spent; finishing costs $1M more and brings $1.5M. Should you finish? Give answer and reasoning.", "Answer: Yes.\nWorking: Future benefit 1.5 > future cost 1.0. The $2M is sunk."],
  "sunk-4": ["Decide: $5M spent; finishing costs $3M; project returns $2M. Should you finish? Give answer and reasoning.", "Answer: No.\nWorking: 2 < 3, regardless of the $5M."],
  "sunk-5": ["Compare: fixed costs vs sunk costs, explain the key difference, and give an example of each", "Answer: Fixed costs don't vary with output but may be avoidable (e.g. by shutting down). Sunk costs can't be avoided at all.\nExample: Fixed cost - a salaried manager whose pay continues unless you shut the division; sunk cost - $200k already paid for non-refundable custom software with no resale value."],
  "sunk-6": ["Explain: overhead allocation error and why it can mislead decisions about product profitability", "Definition: Allocated fixed overhead does not change with the decision; including it can make profitable products look unprofitable.\nExample: A product contributes $8 per unit but after allocating $10 of fixed overhead shows a $2 loss. Dropping it would lose the $8 contribution while the overhead stays the same.\nWhat it tells you: Exclude allocated fixed costs that do not differ between alternatives."],
  "sunk-7": ["Define: relevant costs in decision making and list their key characteristics", "Definition: Costs that differ between the alternatives: future, avoidable costs, including opportunity costs.\nExample: When choosing to process a product further, only the extra processing costs and added revenue are relevant, not the original material cost already incurred.\nWhat it tells you: Focus only on these to make the best forward-looking choice."],
  "sunk-8": ["List: the three costly decision errors in managerial economics", "Answer: Ignoring hidden (opportunity) costs, letting sunk costs drive decisions, and using average instead of marginal analysis."],
  "sunk-9": ["Define: break-even price for an investment, state what NPV=0 means, and explain how to use it", "Definition: The price at which the project's NPV = 0, i.e. covers its avoidable cost per unit. Compare it with the expected price.\nExample: If a project's avoidable cost implies a break-even price of $18 per unit and the expected market price is $22, the NPV is positive.\nWhat it tells you: Invest only if expected price exceeds the break-even price."],
  "costs-1": ["Define: fixed cost, give a business example, and say what it tells you", "Definition: Doesn't change with output in the short run (rent, insurance).\nExample: A factory pays the same rent and insurance whether it produces 100 or 1,000 units.\nWhat it tells you: These costs must be covered regardless of short-run output helping set break-even levels."],
  "costs-2": ["Define: variable cost, give a business example, and say what it tells you", "Definition: Rises with output (materials, hourly labor).\nExample: A bakery buys more flour and pays more hourly wages as it bakes additional loaves.\nWhat it tells you: These costs can be adjusted quickly with output changes so they guide short-run production decisions."],
  "costs-3": ["Formula: average total cost, give both versions of the formula, a numerical example, and say what it tells you", "Formula: Total cost / quantity = AFC + AVC.\nExample: Total cost $15,000 for 1,000 units gives ATC of $15.\nWhat it tells you: Full per-unit cost; compare to price to decide if production is profitable."],
  "costs-4": ["Define: economies of scale, give a business example, and say what it tells you", "Definition: Average cost falls as output rises (spreading fixed costs, specialization).\nExample: A car maker spreads $1M factory rent over more vehicles and workers specialize lowering cost per car from $25k to $18k.\nWhat it tells you: Firms should expand output to cut unit costs until diseconomies begin."],
  "costs-5": ["Define: diseconomies of scale, give a business example, and say what it tells you", "Definition: Average cost rises at large output (coordination and bureaucracy costs).\nExample: A giant firm sees rising per-unit costs from management layers slowing decisions and raising overhead.\nWhat it tells you: Firm may be too big so it should consider splitting units to keep costs low."],
  "costs-6": ["Define: economies of scope, give a business example, and say what it tells you", "Definition: Producing two products together is cheaper than producing them separately (shared assets, brand, distribution).\nExample: A firm makes shampoo and conditioner sharing the same factory equipment brand and delivery trucks.\nWhat it tells you: Diversifying into related products can lower total costs using shared resources."],
  "costs-7": ["Define: learning curve, give a business example, and say what it tells you", "Definition: Average cost falls with cumulative output as workers and firms learn.\nExample: An electronics assembler reduces time per unit from 30 to 15 minutes after building thousands of devices.\nWhat it tells you: Costs drop with experience so early prices may be set low to build volume."],
  "costs-8": ["Define: minimum efficient scale, give a business example, and say what it tells you", "Definition: The smallest output at which average cost is lowest. High MES relative to the market means few firms.\nExample: If MES is 500,000 units but market demand is 1.2M then only two or three firms fit efficiently.\nWhat it tells you: Explains concentrated industries with few large competitors."],
  "costs-9": ["Compare: short run vs long run, give the differences in inputs, a business example, and what it tells you", "Answer: Short run: at least one input fixed. Long run: all inputs variable, including plant size and entry or exit.\nExample: A cafe cannot change its leased space quickly but can build a larger shop or exit in the long run.\nWhat it tells you: Short run has fixed costs; long run allows full adjustment and entry or exit."],
  "costs-10": ["Calculate: Fixed $10k, variable $5 a unit, 1,000 units. What is average total cost? Show the working.", "Answer: $15.\nWorking: (10,000 + 5,000) / 1,000."],
  "costs-11": ["Explain: make vs buy (vertical integration), give the rule for each, a business example, and what it tells you", "Rule: Make when outsourcing would expose you to hold-up on specific investments; buy when the market is competitive and contracts are easy.\nExample: An automaker produces custom transmissions in-house to avoid supplier hold-up after tool investments but buys tires from many competitive suppliers.\nWhat it tells you: Guides vertical integration choices to minimize risks and transaction costs."],
  "sd-1": ["State: the law of demand, then give a business example", "Definition: Price up -> quantity demanded down, other things equal.\nExample: If the price of coffee rises, consumers demand less coffee, other things equal.\nWhat it tells you: Consumers buy less of a good as its price rises."],
  "sd-2": ["State: the law of supply, then give a business example", "Definition: Price up -> quantity supplied up.\nExample: If the price of wheat rises, farmers supply more wheat.\nWhat it tells you: Producers offer more of a good as its price rises."],
  "sd-3": ["List: the demand shifters", "Answer: Income, prices of substitutes and complements, tastes, expectations, number of buyers.\nWhat it tells you: These shift the entire demand curve when they change."],
  "sd-4": ["List: the supply shifters", "Answer: Input costs, technology, number of sellers, prices of other goods sellers could make, expectations.\nWhat it tells you: These shift the entire supply curve when they change."],
  "sd-5": ["Compare: change in demand vs change in quantity demanded, with an example of each", "Answer: Change in demand: the whole curve shifts (a shifter changed). Change in quantity demanded: a move along the curve due to price.\nExample: Income rise shifts demand for cars right. Price drop for cars moves quantity demanded along the curve."],
  "sd-6": ["Define: equilibrium in a market", "Definition: Price where quantity demanded = quantity supplied.\nExample: The intersection of demand and supply curves for apples.\nWhat it tells you: This is the market-clearing price with no pressure to change."],
  "sd-7": ["Explain: what surplus and shortage mean and what prices cause each", "Answer: Price above equilibrium -> surplus (excess supply); below -> shortage (excess demand).\nExample: Price of bread above equilibrium leaves unsold loaves (surplus); below leaves buyers without bread (shortage)."],
  "sd-8": ["Compare: substitutes vs complements, with the effect on demand and an example of each", "Answer: Substitutes: the price of one up -> demand for the other up (coffee and tea). Complements: price up -> demand for the other down (printers and ink).\nWhat it tells you: Related goods affect each others demand depending on whether they replace or go together."],
  "sd-9": ["Compare: normal vs inferior goods in terms of how demand responds to income", "Answer: Normal: demand rises with income. Inferior: demand falls as income rises.\nExample: Normal good like steak; inferior good like ramen noodles."],
  "sd-10": ["Calculate: Demand Qd = 100 - 2P, supply Qs = 20 + 2P. What is equilibrium price and quantity? Show the working.", "Answer: P = 20, Q = 60.\nWorking: Set Qd=Qs so 100-2P=20+2P. Add 2P to both: 100=20+4P. Subtract 20: 80=4P. Divide by 4: P=20. Then Q=20+2 x 20=60."],
  "sd-11": ["State: what happens to equilibrium price and quantity if demand rises with supply unchanged", "Answer: Price up, quantity up.\nExample: Increased popularity of yoga mats raises their price and sales.\nWhat it tells you: New equilibrium is higher on the supply curve."],
  "sd-12": ["State: what happens to equilibrium price and quantity if supply rises (cost falls) with demand unchanged", "Answer: Price down, quantity up.\nExample: Cheaper production tech for phones lowers prices and increases units sold.\nWhat it tells you: New equilibrium is lower on the demand curve."],
  "sd-13": ["Explain: the effects of a price ceiling below equilibrium with an example", "Answer: Shortage, queues, black markets (e.g. rent control).\nWhat it tells you: Prevents market clearing so quantity supplied is below quantity demanded."],
  "sd-14": ["Explain: the effects of a price floor above equilibrium with an example", "Answer: Surplus (e.g. minimum wage -> fewer jobs than workers seeking them, per the standard model).\nWhat it tells you: Quantity supplied exceeds quantity demanded."],
  "sd-15": ["Define: deadweight loss, then list its causes", "Definition: Total surplus lost when output differs from the efficient quantity (from taxes, price controls, market power).\nExample: A tax reducing trades below equilibrium quantity.\nWhat it tells you: Measures lost economic efficiency from market distortions."],
  "elasticity-1": ["Formula: price elasticity of demand", "Formula: % change in quantity demanded / % change in price.\nExample: If price rises 10% and quantity demanded falls 20%, e = -2.\nWhat it tells you: Measures how sensitive quantity demanded is to a price change."],
  "elasticity-2": ["Compare: elastic vs inelastic demand using the |e| thresholds", "Answer: |e| > 1 elastic (buyers sensitive); |e| < 1 inelastic; |e| = 1 unit elastic.\nWhat it tells you: Elastic means buyers are sensitive to price changes; inelastic means they are not sensitive."],
  "elasticity-3": ["Explain: how elasticity affects total revenue when price rises and when revenue is maximized", "Answer: Elastic: raising price lowers revenue. Inelastic: raising price raises revenue. Revenue is maximized at unit elasticity.\nExample: With elastic demand a 10% price rise might cut quantity 20% so total revenue falls.\nWhat it tells you: Guides whether a firm should raise or cut price to boost revenue."],
  "elasticity-4": ["List: the determinants of elasticity and which lead to more elastic demand", "Answer: More substitutes, a bigger budget share, a longer time horizon, and narrowly defined goods -> more elastic.\nExample: A specific brand of coffee has many substitutes so is elastic; all coffee has fewer so is less elastic.\nWhat it tells you: These factors determine how responsive buyers are to price changes."],
  "elasticity-5": ["Calculate: Price up 10%, quantity down 25%. What is the elasticity, is it elastic or inelastic, and what happens to revenue?", "Answer: |e| = 2.5, elastic; revenue falls.\nWorking: 25 / 10 = 2.5. Since |e| > 1 it is elastic so revenue falls when price rises."],
  "elasticity-6": ["Formula: arc (midpoint) elasticity", "Formula: [(Q2 - Q1) / ((Q1 + Q2)/2)] / [(P2 - P1) / ((P1 + P2)/2)].\nWhat it tells you: Uses averages of the two points so it is more accurate for elasticity over a range."],
  "elasticity-7": ["Calculate: Price $10 -> $12, quantity 100 -> 80. What is the midpoint elasticity? Show the working.", "Answer: About -1.22.\nWorking: (-20/90) / (2/11) = -0.222 / 0.182."],
  "elasticity-8": ["Formula: income elasticity of demand and interpret positive, negative and >1 values", "Formula: % change in quantity / % change in income.\nWhat it tells you: Positive = normal good; negative = inferior; > 1 = luxury.\nExample: Income rises 10%, restaurant meals rise 15% -> income elasticity 1.5 so a luxury normal good."],
  "elasticity-9": ["Formula: cross-price elasticity of demand and what positive vs negative values mean", "Formula: % change in quantity of A / % change in price of B.\nWhat it tells you: Positive = substitutes; negative = complements.\nExample: Price of coffee up 10%, tea quantity up 8% -> cross elasticity +0.8 so substitutes."],
  "elasticity-10": ["Formula: optimal markup rule using elasticity", "Formula: (P - MC) / P = 1 / |e|.\nWhat it tells you: Less elastic demand -> higher markup.\nExample: If |e| = 2 then (P - MC)/P = 0.5 so price is double marginal cost."],
  "elasticity-11": ["Calculate: MC $60, demand elasticity -3. What is the profit-maximizing price? Show the working.", "Answer: $90.\nWorking: (P - 60)/P = 1/3, so P = 90."],
  "elasticity-12": ["Compare: firm vs industry elasticity of demand", "Answer: A single brand's demand is more elastic than the industry's, because other brands are close substitutes.\nExample: Demand for one brand of cereal is more elastic than demand for all breakfast cereal.\nWhat it tells you: Individual firms face more elastic demand than the whole industry."],
  "elasticity-13": ["Formula: quick % change in quantity using elasticity and give the example", "Formula: % change in Q ≈ elasticity x % change in P.\nExample: e = -2, price +5% -> quantity -10%.\nWhat it tells you: Useful for quick estimates of how quantity will respond to a price change."],
  "structures-1": ["Define: perfect competition. List its key features, firm behavior, long-run economic profit and price condition.", "Definition: Many firms, identical products, free entry: price takers; long-run economic profit = 0; P = MC.\nExample: Thousands of wheat farmers sell identical grain and each takes the prevailing market price.\nWhat it tells you: Free entry drives long-run economic profits to zero; firms have no pricing power and produce where P = MC."],
  "structures-2": ["Define: monopolistic competition. List its key features, pricing power and long-run economic profit tendency.", "Definition: Many firms, differentiated products, free entry: some pricing power, but long-run economic profit tends to zero.\nExample: Coffee shops differentiate by location, atmosphere and menu; new ones open if profits are high.\nWhat it tells you: Differentiation gives short-run pricing power but entry erodes economic profits to zero over time."],
  "structures-3": ["Define: oligopoly. List its key features including firm interdependence, behavior and entry conditions.", "Definition: A few interdependent firms; strategic behavior (game theory); barriers to entry.\nExample: Two or three airlines on a route set prices while watching what the others will do.\nWhat it tells you: Firms must anticipate rivals' reactions; game theory helps predict pricing and output choices."],
  "structures-4": ["Define: monopoly. List its key features, pricing rule, price vs MC outcome and efficiency effect.", "Definition: A single seller with high entry barriers; sets MR = MC; price > MC; deadweight loss.\nExample: A firm with a patent on a cancer drug charges well above marginal cost.\nWhat it tells you: Monopoly restricts output below competitive levels, raising prices and creating deadweight loss."],
  "structures-5": ["List: the main barriers to entry with one-sentence descriptions of each.", "Answer: Economies of scale, patents, licenses, control of key inputs, network effects, switching costs, brand.\nExample: A patent on a new smartphone feature blocks rivals for 20 years.\nWhat it tells you: Barriers allow incumbent firms to sustain above-normal profits by deterring new entrants."],
  "structures-6": ["Explain: long-run entry and exit in markets. Include what happens with profits, losses and the role of sustainable advantage.", "Definition: Profits attract entry and push price toward average cost; losses cause exit. Above-normal profit erodes without a sustainable advantage.\nExample: High profits at a new food-truck park draw more trucks until prices fall and profits normalize.\nWhat it tells you: Without a sustainable edge, competition eliminates economic profits in the long run."],
  "structures-7": ["Define: sustainable competitive advantage. State what it requires to earn above-average profit long term.", "Definition: Earning above-average profit long term requires something rivals can't easily copy: cost advantage, differentiation, or barriers.\nExample: Costco's low-cost membership model is hard for rivals to replicate at the same scale.\nWhat it tells you: Only firms with such advantages can maintain economic profits after long-run entry and exit."],
  "structures-8": ["List: Porter's Five Forces that shape industry competition.", "Answer: Rivalry, threat of entry, threat of substitutes, buyer power, supplier power.\nExample: In soft drinks, high rivalry and buyer power from large retailers like Walmart reduce profitability.\nWhat it tells you: Managers use the forces to assess industry attractiveness and choose defensive strategies."],
  "structures-9": ["Define: Herfindahl-Hirschman Index (HHI). Give the formula and state the 2023 and 2010 US merger guideline thresholds.", "Definition: Sum of squared market shares (%). Under the 2023 US merger guidelines, over 1,800 = highly concentrated (the 2010 guidelines used 2,500).\nFormula: HHI = sum of each firm's (market share percent squared)\nExample: Four equal 25% firms give HHI of 2,500.\nWhat it tells you: Higher values signal greater concentration and possible antitrust concern for mergers."],
  "structures-10": ["Calculate: Four firms with shares 40, 30, 20, 10%. What is the HHI? Show the working.", "Answer: 3,000\nWorking: 1600 + 900 + 400 + 100."],
  "structures-11": ["Define: the indifference principle (Froeb). Explain what happens in equilibrium when assets or workers are mobile.", "Definition: If assets or workers are mobile, in equilibrium all uses must be equally attractive: differences get bid away (compensating wage differentials, house prices).\nExample: Dangerous mining jobs pay higher wages so workers are indifferent between them and safer office jobs.\nWhat it tells you: Market forces eliminate non-compensated differences; useful for predicting wage or price gaps."],
  "structures-12": ["Define: natural monopoly. Explain why it occurs, give an example and note typical policy response.", "Definition: One firm can supply the market at lower cost than several, because of huge fixed costs (utilities). Often regulated.\nExample: A single set of power lines for a city is cheaper than building duplicate networks.\nWhat it tells you: Regulation caps prices to balance efficiency of single provider against monopoly pricing."],
  "pricing-1": ["State: the monopoly pricing rule for choosing quantity and price", "Rule: Pick the quantity where MR = MC, then charge the highest price demand allows for that quantity.\nExample: A widget monopolist calculates MR=MC at 1,000 units; the demand curve allows charging $15 at that Q.\nWhat it tells you: This maximizes monopoly profit by balancing marginal revenue with cost."],
  "pricing-2": ["Explain: the problems with cost-plus pricing", "Problems: It ignores demand (elasticity) and often uses average rather than marginal cost.\nExample: A restaurant using average cost plus 50% might price a dish at $20 even if demand is elastic and MC is only $5, losing sales.\nWhat it tells you: This can lead to suboptimal prices that miss maximum profit."],
  "pricing-3": ["Define: price discrimination and what it is based on instead of cost", "Definition: Charging different prices to different customers for the same good, based on willingness to pay rather than cost.\nExample: Airlines charging business travelers more than leisure travelers for identical seats.\nWhat it tells you: It captures more consumer surplus to increase profits."],
  "pricing-4": ["Define: first-degree price discrimination and its alternative name", "Definition: Each customer pays their own maximum willingness to pay (perfect discrimination).\nExample: A consultant quoting each client a unique fee based on their exact perceived value.\nWhat it tells you: The seller extracts all consumer surplus for maximum profit."],
  "pricing-5": ["Define: second-degree price discrimination and how customers choose", "Definition: Indirect: customers self-select via menus such as volume discounts, versions or quality tiers.\nExample: A software firm offers basic free and paid pro versions; high-value users pick pro.\nWhat it tells you: Customers reveal their type by choice without direct identification."],
  "pricing-6": ["Define: third-degree price discrimination, examples of groups and which pays more", "Definition: Direct: different prices for identifiable groups (students, seniors, regions). Charge more to the less elastic group.\nExample: Museums charge seniors less since their demand is more elastic than working adults.\nWhat it tells you: Segmenting by elasticity raises total revenue and profit."],
  "pricing-7": ["List: the three conditions required for price discrimination", "Answer: Market power, ability to identify or sort customers, and preventing resale (arbitrage).\nExample: A patent holder can charge more in rich countries if it blocks cheap re-export to poor ones.\nWhat it tells you: These let the firm separate markets and charge differently for more profit."],
  "pricing-8": ["Define: bundling and when it is profitable", "Definition: Selling goods together; profitable when customers' valuations are negatively correlated.\nExample: Customer A values item X high and Y low while B is opposite; bundling equalizes total WTP.\nWhat it tells you: It reduces variation in valuations to capture more total surplus."],
  "pricing-9": ["Calculate: A values Word $100 Excel $40; B values Word $40 Excel $100. Zero marginal cost. Best separate prices and revenues vs bundle?", "Answer: Separate: $100 each sells one of each = $200 (beats $40 each = $160). Bundle at $140 sells to both = $280.\nWorking: Separate at $100: A buys Word B buys Excel for $200 total. At $40 both buy both for $160. Bundle at $140: each gets 140 value so both buy for $280 total."],
  "pricing-10": ["Define: two-part tariff, give examples and how to set the prices", "Definition: An entry fee plus a per-unit price (gym membership plus fees, Costco). Set the unit price near MC and capture surplus with the fee.\nExample: Gym charges $50 monthly fee then $5 per class when MC is near zero.\nWhat it tells you: It extracts fixed surplus while setting efficient marginal usage."],
  "pricing-11": ["Define: versioning and how it helps customer sorting", "Definition: Offering a 'damaged' or premium version so customers sort themselves by willingness to pay.\nExample: Software sold with full features vs a cheaper version with features disabled.\nWhat it tells you: Enables self-selection for second-degree price discrimination."],
  "pricing-12": ["Define: peak-load pricing and when it applies with examples", "Definition: Charging more when demand is high and capacity is tight (airlines, electricity, ride-share surge).\nExample: Ride-share apps add surge multipliers during rush hour or events.\nWhat it tells you: Allocates limited capacity to highest-value users and signals need for more capacity."],
  "pricing-13": ["Calculate: Adults elasticity -2; students -4. MC $10. What prices with the markup rule? Show workings", "Answer: Adults $20 ((P-10)/P = 1/2); students $13.33 ((P-10)/P = 1/4).\nWorking: (P-MC)/P = 1 over absolute elasticity. Adults: (P-10)/P=0.5 solves to P=20. Students: (P-10)/P=0.25 solves to P approx 13.33."],
  "pricing-14": ["Compare: penetration pricing vs skimming with one example of each", "Answer: Penetration: a low entry price to win share and scale. Skimming: start high for eager buyers, then cut the price.\nExample: Penetration - budget airline launches routes at low fares to gain volume. Skimming - new smartphone starts expensive then drops price over months.\nWhat it tells you: Penetration for scale economies; skimming to harvest high initial WTP."],
  "game-1": ["Define: game theory, then give a business example", "Definition: Analysis of strategic decisions where your payoff depends on others' choices.\nExample: Two firms choosing ad budgets where each profit depends on the rival's choice.\nWhat it tells you: Helps predict outcomes in competitive situations like pricing or advertising wars."],
  "game-2": ["Define: dominant strategy, then give a business example", "Definition: Best for you whatever the other player does.\nExample: In a pricing game a firm always chooses low price as it pays more whether rival chooses high or low.\nWhat it tells you: If both have one the outcome is predictable even if both would prefer another result."],
  "game-3": ["Define: Nash equilibrium, then give a business example", "Definition: A set of strategies where no player can gain by changing strategy alone.\nExample: Both firms in a market set low prices; neither gains by raising price if the other stays low.\nWhat it tells you: This stable point is the likely outcome of the strategic game."],
  "game-4": ["Define: prisoner's dilemma, then give two business examples", "Definition: Each player's dominant strategy (defect) leads to an outcome worse for both than cooperating.\nExample: price wars, ad wars.\nWhat it tells you: Rational choices produce collectively bad results for all players."],
  "game-5": ["List: ways of escaping the prisoner's dilemma", "Answer: Repeated play (tit-for-tat), contracts, mergers, meet-the-competition clauses (with legal limits on collusion).\nWhat it tells you: These can help reach the better cooperative outcome."],
  "game-6": ["Define: sequential game, then say how to solve it and give an example", "Definition: Players move in turn; solve by backward induction from the last move.\nExample: A firm decides on capacity knowing a rival will respond afterward.\nWhat it tells you: The order of moves can change the final outcome."],
  "game-7": ["Define: credible commitment, then explain what makes it believable", "Definition: A threat or promise that is believable because carrying it out is in your interest, or because you have tied your hands.\nExample: A firm publicly builds extra capacity so fighting a rival becomes its best response.\nWhat it tells you: Only believable commitments influence the other player's choice."],
  "game-8": ["Define: first-mover advantage, then give examples of locking in an outcome", "Definition: Moving first can lock in an outcome (capacity, standards), if the commitment is credible and irreversible.\nExample: Setting a technical standard before rivals or building large capacity first.\nWhat it tells you: In sequential games the first player can secure a better payoff."],
  "game-9": ["Define: bargaining power, then explain how to increase your share", "Definition: Set by each side's alternative to agreement (BATNA). Improve your alternative or worsen theirs to win a bigger share.\nExample: A seller lines up a second buyer to strengthen its position.\nWhat it tells you: Stronger BATNA gives you more of the gains from trade."],
  "game-10": ["Define: BATNA, then state the rule for accepting deals", "Definition: Best alternative to a negotiated agreement. Never accept a deal worse than it.\nExample: If your best outside job offer is $90k do not accept $80k.\nWhat it tells you: It sets the minimum you will accept in any negotiation."],
  "game-11": ["Define: bargaining range (ZOPA), then state when a deal is possible", "Definition: Between the seller's minimum (reservation price) and the buyer's maximum. A deal is possible only if buyer max > seller min.\nExample: Seller reservation $90 buyer max $120 so range is $90 to $120.\nWhat it tells you: No overlap means no mutually beneficial agreement exists."],
  "game-12": ["Calculate: find the equilibrium. Payoffs (You, Rival): both High (10,10); you High/they Low (2,14); you Low/they High (14,2); both Low (5,5). Say what it is and why.", "Answer: Both Low (5,5).\nWorking: Low is dominant for each (14 > 10, 5 > 2): a prisoner's dilemma."],
  "game-13": ["Define: mixed strategy, then give two examples", "Definition: Randomizing between choices so opponents can't predict you (penalty kicks, audits).\nExample: A firm randomly offering discounts or a regulator randomly auditing tax returns.\nWhat it tells you: It prevents opponents from exploiting any predictable pattern."],
  "game-14": ["Define: hold-up problem, then say how it is solved and give an example", "Definition: After one party makes a relationship-specific investment, the other can renegotiate to grab its value. Solved by contracts or integration.\nExample: A supplier builds a custom machine for one buyer who then demands a price cut.\nWhat it tells you: Without safeguards valuable specific investments may be avoided."],
  "uncert-1": ["Formula: expected value", "Formula: Sum of (probability x payoff) over the outcomes.\nExample: 60% chance of +$100, 40% chance of -$50: (0.6 x 100)+(0.4 x -50)=60-20=$40.\nWhat it tells you: Long-run average if repeated many times; pick option with highest EV to maximize payoff."],
  "uncert-2": ["Calculate: 60% chance of +$100k, 40% chance of -$50k. What is the expected value? Show the working.", "Answer: +$40k\nWorking: 0.6 x 100k = +60k; 0.4 x -50k = -20k; 60k-20k = +40k."],
  "uncert-3": ["Define: risk aversion, then explain its relation to insurance", "Definition: Preferring a sure amount to a gamble with the same expected value; willing to pay to reduce risk (insurance).\nExample: Person pays insurance premium above expected loss to avoid big financial hit from uncertain event."],
  "uncert-4": ["Formula: value of information, then state the rule about how much to pay", "Formula: Expected value with the information - expected value without it.\nWhat it tells you: Never pay more than this."],
  "uncert-5": ["Describe: oral (English) auction including bidding process, what winner pays, and optimal strategy", "Description: Ascending bids; the winner pays about the second-highest value. Bidding up to your value is optimal.\nExample: Bids rise step by step on a used car; last bidder wins paying just over what the runner-up valued it at."],
  "uncert-6": ["Describe: sealed-bid first-price auction including what winner pays and how bidders adjust", "Description: Highest bid wins and pays its own bid, so bidders shade bids below their value.\nExample: True value $10k but bid $7k to win and keep some surplus if successful."],
  "uncert-7": ["Describe: second-price (Vickrey) auction including what winner pays and optimal bidding strategy", "Description: Highest bid wins and pays the second-highest bid. Bidding your true value is a dominant strategy.\nExample: Value item at $500; bid exactly $500 even if others bid lower since you pay their amount."],
  "uncert-8": ["Define: winner's curse in common-value auctions and the bidding advice", "Definition: In common-value auctions the winner is likely the one who overestimated the value most. Bid below your estimate.\nExample: Bidding on oil rights where true value is same for all; adjust estimate down to avoid overpaying."],
  "uncert-9": ["Explain: revenue equivalence including assumptions and result", "Explanation: Under standard assumptions (risk-neutral, independent private values), the common auction formats yield the same expected revenue.\nWhat it tells you: Seller expects same revenue from English, first-price sealed, or Vickrey formats."],
  "uncert-10": ["Describe: decision tree and how to use it for choices under uncertainty", "Description: Map choices and chance events, attach probabilities and payoffs, then work backward picking the best expected value.\nExample: New venture with 70% success payoff $200k or 30% loss $80k; fold back to choose max EV branch."],
  "asymmetric-1": ["Define: asymmetric information in one sentence then give a business example", "Definition: One party to a deal knows more than the other.\nExample: A used car seller knows if there are hidden defects but the buyer cannot easily tell.\nWhat it tells you: It can lead to market failures like adverse selection or moral hazard."],
  "asymmetric-2": ["Define: adverse selection, state when the hidden information occurs and give the lemons and insurance examples", "Definition: Hidden information BEFORE the deal: the worst types are most eager to participate (lemons, high-risk insurance buyers).\nWhat it tells you: The uninformed party may end up with mostly bad risks as the worst types self-select into the deal."],
  "asymmetric-3": ["Define: moral hazard, state when the hidden action occurs and give the insured drivers example", "Definition: Hidden action AFTER the deal: behavior changes because someone else bears the cost (insured drivers take less care).\nWhat it tells you: The party whose behavior is hidden may take more risks when costs are shifted to others."],
  "asymmetric-4": ["Define: market for lemons (Akerlof), then explain what happens when buyers cannot tell quality", "Definition: Buyers can't tell quality, so they pay average prices; good cars exit; the market can unravel.\nExample: In the used car market only lemons remain for sale at the average price buyers are willing to pay."],
  "asymmetric-5": ["Define: signaling, explain how the informed party uses a costly action and give two examples", "Definition: The informed party credibly reveals its type with a costly action that low types can't afford to copy (warranties, degrees).\nExample: A car maker offers a long warranty to signal high quality since only good makers can afford the expected repair costs."],
  "asymmetric-6": ["Define: screening, explain how the uninformed party designs choices and give two examples", "Definition: The uninformed party designs choices so types sort themselves (deductible menus, probation periods).\nExample: An employer offers a low starting salary with a probation period that high-ability workers are more willing to accept."],
  "asymmetric-7": ["List: the fixes for adverse selection then briefly describe one", "Answer: Screening, signaling, warranties, reputation, third-party certification, mandatory pooling (e.g. insurance mandates).\nExample: Mandatory pooling such as insurance mandates prevents only high-risk types from buying coverage."],
  "asymmetric-8": ["List: the fixes for moral hazard then briefly describe one", "Answer: Monitoring, deductibles and co-pays, performance-based pay, bonding, reputation.\nExample: Deductibles make the insured bear part of any loss so they take more care."],
  "asymmetric-9": ["Explain: how a deductible can reduce moral hazard and also screen for risk", "Answer: Reduces moral hazard (the insured bears part of the loss) and screens for risk (low-risk people pick high deductibles).\nWhat it tells you: It improves incentives to avoid losses and reveals customer risk type through their policy choice."],
  "asymmetric-10": ["Explain: how a warranty can signal quality to buyers", "Answer: A signal of quality: a maker of a bad product can't afford to offer a long warranty.\nWhat it tells you: Only producers of high-quality goods can credibly commit to warranties without losing money on claims."],
  "asymmetric-11": ["Decide: adverse selection or moral hazard? A bank's riskiest applicants most want loans. Explain", "Answer: Adverse selection (hidden type before the deal).\nWhat it tells you: The bank faces a pool of worse-than-average applicants and should use screening devices such as collateral requirements."],
  "asymmetric-12": ["Decide: adverse selection or moral hazard? A borrower takes bigger risks after getting the loan. Explain", "Answer: Moral hazard (hidden action after the deal).\nWhat it tells you: The lender should monitor use of funds or add covenants to prevent the borrower from shifting to riskier behavior."],
  "incentives-1": ["Define: principal-agent problem, give a business example, and state what it tells you", "Definition: An agent (employee, manager) acting for a principal (owner) has different goals and better information.\nExample: A restaurant owner (principal) hires a manager (agent) who may slack off on busy nights when the owner is absent.\nWhat it tells you: Owners must design incentives or monitoring to align the agent's actions with their goals."],
  "incentives-2": ["Define: incentive-pay trade-off, give a business example, and state what it tells you", "Definition: Stronger performance pay improves effort but loads risk on the agent, who must be paid more to bear it.\nExample: A sales manager gets a large bonus tied to revenue targets; this motivates effort but if revenue swings with the economy the risk-averse manager demands higher average pay.\nWhat it tells you: Firms must balance improved effort against the extra compensation needed for the agent to accept risk."],
  "incentives-3": ["Define: pay on revenue vs profit, give a business example, and state what it tells you", "Definition: Revenue pay pushes sales staff to cut price and chase volume; profit or margin pay aligns with owners.\nExample: A car salesperson paid on revenue offers big discounts to boost unit sales and personal pay, reducing company profit; paying on margin leads to higher prices.\nWhat it tells you: The performance metric must be chosen so employee behavior aligns with owner profitability goals."],
  "incentives-4": ["Define: fixed salary vs commission, give a business example, and state what it tells you", "Definition: Salary: low risk, weak effort incentive (needs monitoring). Commission: strong incentive, more risk, can encourage gaming.\nExample: A real-estate agent on fixed salary may show few houses if hard to monitor; on commission the agent works harder but may steer clients to quick high-commission deals.\nWhat it tells you: Choose based on monitoring ease, risk tolerance, and risk of undesirable behaviors like gaming."],
  "incentives-5": ["Define: gaming performance metrics, give a business example, and state what it tells you", "Definition: People optimize the measure, not the goal (Goodhart's law). Use multiple, hard-to-manipulate measures.\nExample: Teachers paid for high student test scores teach only test material and neglect broader skills; combining scores with classroom observations and peer reviews limits gaming.\nWhat it tells you: Carefully select multiple metrics that are hard to manipulate to avoid unintended behaviors."],
  "incentives-6": ["Define: relative performance evaluation, give a business example, and state what it tells you", "Definition: Pay based on performance relative to peers, filtering out common shocks (tournaments, rankings).\nExample: A store manager's bonus depends on sales growth versus other stores in the same region, so a recession hurting all stores does not unfairly reduce the bonus.\nWhat it tells you: It improves incentives by shielding pay from external shocks outside the agent's control."],
  "incentives-7": ["Define: stock options for CEOs, give a business example, and state what it tells you", "Definition: Align managers with shareholders, but can encourage short-termism or excessive risk-taking.\nExample: A CEO with options might delay R&D spending to hit short-term earnings and boost stock price for option gains, or pursue risky mergers with high upside.\nWhat it tells you: Options improve alignment but need safeguards like longer vesting to reduce short-termism and excess risk."],
  "incentives-8": ["Define: centralization vs decentralization, give a business example, and state what it tells you", "Definition: Centralize when coordination matters and information is easy to send up; decentralize when local knowledge matters.\nExample: A hotel chain centralizes purchasing for volume discounts and brand standards but lets local managers set room rates based on their market knowledge.\nWhat it tells you: Choose structure by weighing coordination needs against the value of local information."],
  "incentives-9": ["Define: transfer pricing, give a business example, and state what it tells you", "Definition: The price one division charges another. Setting it at marginal or opportunity cost avoids distorting internal decisions.\nExample: A computer maker's chip division transfers chips to the assembly division at marginal cost, so assembly orders the company-optimal volume instead of treating the transfer price as too high.\nWhat it tells you: Proper transfer prices let decentralized units make choices that maximize total firm profit."],
  "incentives-10": ["Define: profit center vs cost center, give a business example, and state what it tells you", "Definition: Profit center: judged on profit. Cost center: judged on meeting output at minimum cost. The metric drives behavior.\nExample: An IT department run as a cost center focuses on delivering required support at lowest cost; as a profit center it may charge high internal fees and cut quality to raise its own reported profit.\nWhat it tells you: The metric chosen strongly influences whether managers emphasize cost control or overall profitability."],
  "incentives-11": ["Define: efficiency wage, give a business example, and state what it tells you", "Definition: Paying above market to boost effort and loyalty and cut turnover: the job becomes costly to lose.\nExample: A factory pays $18 per hour when similar jobs pay $14; workers exert more effort to avoid losing the premium job, show higher loyalty, and quit less often.\nWhat it tells you: Above-market wages can lower total costs when productivity gains and reduced turnover outweigh the higher pay."],
  "incentives-12": ["Define: multitask problem, give a business example, and state what it tells you", "Definition: Rewarding only measurable tasks causes neglect of unmeasured ones (quality, teamwork).\nExample: A customer-service rep paid only for calls completed rushes every call, harming service quality and teamwork; adding quality scores and team metrics corrects this.\nWhat it tells you: Incentives must cover all key tasks or use broader measures to prevent neglect of important but hard-to-measure activities."],
  "failure-1": ["Define: externality, then give one example of negative and one of positive", "Definition: A cost or benefit falling on third parties outside the transaction.\nExample: Negative - factory pollution harming nearby residents. Positive - vaccinations reducing disease spread to others.\nWhat it tells you: Markets ignore these so overproduce negative and underproduce positive externalities."],
  "failure-2": ["Explain: negative externality result including market outcome with example and the fixes", "Answer: The market overproduces (pollution). Fixes: Pigouvian tax, cap-and-trade, regulation.\nExample: A factory pollutes a river imposing cleanup costs on downstream communities not part of the sale.\nWhat it tells you: Social cost exceeds private cost leading to too much output; policies like a tax equal to external cost can reach efficient level."],
  "failure-3": ["Explain: positive externality result including market outcome with example and the fixes", "Answer: The market underproduces (vaccines, R&D). Fixes: subsidies, patents.\nExample: A firm doing R&D that creates knowledge others can use without paying leads to less innovation than society needs.\nWhat it tells you: Social benefit exceeds private benefit so too little is produced; subsidies or patents increase activity toward the social optimum."],
  "failure-4": ["Define: public good, give the key characteristics with example, and explain the free rider issue", "Definition: Non-rival and non-excludable (national defense). Free riders lead to underprovision.\nExample: National defense protects every citizen regardless of tax payment.\nWhat it tells you: Private markets provide too little because non-payers cannot be excluded so government often supplies them."],
  "failure-5": ["Define: free-rider problem, explain why it happens and its effect", "Definition: People benefit without paying, so voluntary provision falls short.\nExample: Viewers enjoying public TV broadcasts without donating to funding drives.\nWhat it tells you: It causes underprovision of public goods as private suppliers cannot recover costs leading to reliance on government."],
  "failure-6": ["State: the Coase theorem, then give a concrete example", "Definition: With clear property rights and low transaction costs, private bargaining reaches the efficient outcome regardless of who holds the rights.\nExample: A polluting factory and affected residents negotiate compensation or reduction; outcome is efficient whether residents or factory initially holds the right.\nWhat it tells you: Private deals can solve externality problems efficiently without government intervention when conditions hold."],
  "failure-7": ["Explain: tragedy of the commons with its result an example and what it leads to", "Answer: Shared resources with open access get overused (overfishing).\nExample: Fishermen in an open-access lake each catch as much as possible ignoring impact on future fish stocks for everyone.\nWhat it tells you: Resources are depleted faster than optimal; solutions like property rights or quotas can prevent overuse."],
  "failure-8": ["Explain: antitrust laws including the Sherman Act and Clayton Act", "Answer: Bans price-fixing and monopolization; mergers are reviewed (Clayton Act) for reducing competition.\nExample: Two rival firms secretly agreeing on prices would violate Sherman Act and face fines or other penalties.\nWhat it tells you: Protects competition to avoid higher prices and lower output from monopolies or cartels."],
  "failure-9": ["Explain in one sentence: how a stronger dollar affects imports and US exports then give an example", "Answer: A stronger dollar makes imports cheaper and US exports less competitive.\nExample: After dollar strengthens a $20k European car costs fewer dollars while US cars become more expensive abroad reducing sales.\nWhat it tells you: Increases imports and reduces exports potentially widening the trade deficit."]
};
});
